  "Installed globally. Studio's OpenCode sessions load no skills, so these are not enabled in them.":
    "전역으로 설치됨. Studio의 OpenCode 세션은 스킬을 불러오지 않아서, 이 스킬은 거기서 켜져 있지 않아요.",
