  "Inventory unavailable. Refresh to retry.": "목록을 불러올 수 없어요. 새로 고침해서 다시 시도하세요.",
  "Invite a friend": "친구 초대하기",
  "Invite friends": "친구 초대",
  "Invite link copied": "초대 링크를 복사했어요",
  "It asks to:": "요청하는 권한:",
  "It closed before it opened. Try again.": "열리기 전에 닫혔어요. 다시 시도하세요.",
  "It couldn’t start on this Mac.": "이 Mac에서 시작하지 못했어요.",
  "It ended before it could write up the build.": "빌드 요약을 쓰기 전에 끝났어요.",
  "It finishes its own setup the first time it opens.": "처음 열 때 스스로 설정을 마쳐요.",
  "It hasn't started yet.": "아직 시작하지 않았어요.",
  "It installs when you relaunch; Genex tells you when it's ready.":
    "다시 시작하면 설치돼요. 준비되면 Genex가 알려 줄게요.",
  "It is on and stays on: its new code runs as soon as it loads, and each of its tools asks you again before it runs.":
    "켜진 상태로 유지돼요. 새 코드는 불러오는 즉시 실행되고, 각 도구는 실행 전에 다시 확인을 요청해요.",
  "It isn’t on this Mac any more. Install it again.": "이제 이 Mac에 없어요. 다시 설치하세요.",
  "It keeps downloading if you go back.": "뒤로 가도 다운로드는 계속돼요.",
  "It keeps your scripts as files in this game's folder and tells Genex which Studio is this game's.":
    "스크립트를 이 게임 폴더에 파일로 보관하고, 어느 Studio가 이 게임의 것인지 Genex에 알려 줘요.",
  "It kept getting this wrong, so it stopped to save your credits.": "계속 잘 안 돼서 크레딧을 아끼려고 멈췄어요.",
  "It leaves Play and genex.games and goes back to drafts. The direct link still works, and plays and likes stay if it’s published again.":
    "플레이와 genex.games에서 내려가고 초안으로 돌아가요. 직접 링크는 계속 작동하고, 다시 게시하면 플레이 수와 좋아요도 그대로 남아요.",
  "It may need the setup scripts its packages came with, which didn’t run.":
    "패키지와 함께 온 설정 스크립트가 실행되지 않았는데, 그게 필요할 수도 있어요.",
  "It merged this part's work without a reviewer's verdict. The reviewers score parts that build in steps; this one was built in one session.":
    "리뷰어 판정 없이 이 파트의 작업을 합쳤어요. 리뷰어는 단계별로 만드는 파트를 채점하는데, 이 파트는 한 세션에서 만들어졌어요.",
  "It merges into your build when the lead integrates this part.":
    "메인 에이전트가 이 파트를 통합하면 빌드에 합쳐져요.",
  "It needs macOS {version} or later.": "macOS {version} 이상이 필요해요.",
  "It never uses password managers, Windows Settings, password prompts or Genex.":
    "비밀번호 관리자, Windows 설정, 비밀번호 입력 창, Genex는 절대 사용하지 않아요.",
  "It ran into an error": "오류가 발생했어요",
  "It runs at Genex's moments: {steps}; those steps don't ask you first.":
    "Genex의 다음 시점에 실행돼요: {steps}. 이 단계들은 미리 확인을 요청하지 않아요.",
  "It runs with your access: Genex doesn't sandbox its code.":
    "사용자 권한으로 실행돼요. Genex는 이 코드를 샌드박스에 격리하지 않아요.",
  "It runs, but no reviewer compared it with the game you had.":
    "실행은 되지만, 리뷰어가 이전 게임과 비교하지 않았어요.",
  "It shows up here as soon as it runs.": "실행되면 바로 여기에 나타나요.",
  "It starts off: turn it on in Plugins; each of its tools asks you before it runs.":
    "처음에는 꺼져 있어요. ‘플러그인’에서 켜 주세요. 각 도구는 실행 전에 확인을 요청해요.",
  "It stopped before this was fixed.": "고치기 전에 멈췄어요.",
  "It treats this as a {kind} game — that decides the controls it drives before every look, and who reviews it.":
    "이 게임을 “{kind}” 유형으로 다뤄요. 그래서 매번 살펴보기 전에 쓰는 조작과 누가 리뷰할지가 정해져요.",
  "It turns on when installed: agents in all your games can use it from your next message.":
    "설치하면 바로 켜져요. 다음 메시지부터 모든 게임의 에이전트가 쓸 수 있어요.",
  "It was paused before it could write up the build.": "빌드 요약을 쓰기 전에 일시 정지됐어요.",
  "It's no longer there.": "더 이상 없어요.",
  "It's switched on in Studio's settings. Studio answers once a place is open: open one in Studio, or press New Roblox game.":
    "Studio 설정에서 켜졌어요. 플레이스가 열리면 Studio가 응답해요. Studio에서 하나를 열거나 ‘새 Roblox 게임’을 누르세요.",
  "It's switched on in Studio's settings. Studio answers once it has finished opening.":
    "Studio 설정에서 켜졌어요. Studio가 다 열리면 응답해요.",
  "Its author no longer shares it.": "작성자가 더 이상 공유하지 않아요.",
  "Its code runs on your computer like an app you install. It isn't sandboxed.":
    "이 코드는 설치한 앱처럼 컴퓨터에서 실행돼요. 샌드박스에 격리되지 않아요.",
  "Its creator hasn’t shared this game’s project yet, so it can’t be remixed.":
    "만든 사람이 아직 이 게임의 프로젝트를 공유하지 않아서 리믹스할 수 없어요.",
  "Its files are in your game folder, waiting for the lead to use them.":
    "파일이 게임 폴더에 있고, 메인 에이전트가 쓰기를 기다리고 있어요.",
  "Its own scene": "독립된 장면",
  "Its packages aren’t installed yet — “{install}” runs on one press.":
    "패키지가 아직 설치되지 않았어요 — 한 번 누르면 “{install}” 명령이 실행돼요.",
  "Its packages aren’t installed yet.": "패키지가 아직 설치되지 않았어요.",
  "Its project didn’t go, so no one can remix it yet.": "프로젝트가 전송되지 않아서 아직 아무도 리믹스할 수 없어요.",
  "Its project is too big to remix: Genex keeps up to 5 GB and 5,000 files.":
    "프로젝트가 너무 커서 리믹스할 수 없어요. Genex는 5GB, 파일 5,000개까지 보관해요.",
  "Its session failed before it delivered anything.": "아무것도 전달하기 전에 세션이 실패했어요.",
  "Its source is your own repository: run genex make-remixable in the game’s folder to allow remixing.":
    "소스가 내 저장소에 있어요. 리믹스를 허용하려면 게임 폴더에서 genex make-remixable을 실행하세요.",
  "Its steps at Genex's moments changed (hooks, observers, locks, folders or harness tools), so it wasn't reloaded: load it again with Load local plugin… to review them":
    "Genex의 각 시점에서 이 플러그인이 하는 단계(훅, 옵저버, 잠금, 폴더, Harness 도구)가 바뀌어서 다시 불러오지 않았어요. 확인하려면 ‘로컬 플러그인 불러오기…’로 다시 불러오세요",
