  Rights: "권리",
  "Roblox Studio closed. It asked to save anything unsaved first.":
    "Roblox Studio를 닫았어요. 닫기 전에 저장하지 않은 내용을 저장할지 물어봤어요.",
  "Roblox Studio didn't say what {name} is. If a play test or a dialog is open in Studio, finish it, then choose the place again.":
    "Roblox Studio가 {name} 정보를 알려 주지 않았어요. Studio에 플레이 테스트나 대화 상자가 열려 있다면 끝낸 다음 플레이스를 다시 고르세요.",
  "Roblox Studio is already on this computer.": "Roblox Studio가 이미 이 컴퓨터에 있어요.",
  "Roblox Studio is already open.": "Roblox Studio가 이미 열려 있어요.",
  "Roblox Studio is installed and set up.": "Roblox Studio가 설치되고 설정됐어요.",
  "Roblox Studio is on this computer": "Roblox Studio가 이 컴퓨터에 있어요",
  "Roblox Studio is open and answering Genex.": "Roblox Studio가 열려 있고 Genex에 응답하고 있어요.",
  "Roblox Studio is open, and Genex adds its helper only while Studio is closed. Restart Studio closes it, sets it up and opens it again.":
    "Roblox Studio가 열려 있는데, Genex는 Studio가 닫혀 있을 때만 도우미를 추가해요. ‘Studio 다시 시작’을 누르면 닫고, 설정한 다음 다시 열어요.",
  "Roblox Studio is open. Genex changes Studio's settings only while it is closed: press Restart Studio, or turn the switch on yourself in Studio.":
    "Roblox Studio가 열려 있어요. Genex는 Studio가 닫혀 있을 때만 Studio 설정을 바꿔요. ‘Studio 다시 시작’을 누르거나 Studio에서 직접 스위치를 켜세요.",
  "Roblox Studio is open. Genex is waiting for it to answer.":
    "Roblox Studio가 열려 있어요. Genex가 응답을 기다리고 있어요.",
  "Roblox Studio is opening again with the Genex helper.": "Roblox Studio가 Genex 도우미와 함께 다시 열리고 있어요.",
  "Roblox Studio is set up but not open.": "Roblox Studio가 설정됐지만 열려 있지 않아요.",
  "Roblox Studio is still open. If it asked to save your place, answer it, then press Quit Studio again.":
    "Roblox Studio가 아직 열려 있어요. 플레이스를 저장할지 물었다면 답한 다음 ‘Studio 종료’를 다시 누르세요.",
  "Roblox Studio is still open. If it asked to save your place, answer it, then press Restart Studio again.":
    "Roblox Studio가 아직 열려 있어요. 플레이스를 저장할지 물었다면 답한 다음 ‘Studio 다시 시작’을 다시 누르세요.",
  "Roblox Studio is still open, and nobody signed in to Roblox there in time. Sign in there, then press Set it up for me so Genex can finish.":
    "Roblox Studio가 아직 열려 있고, 제시간에 Roblox 로그인이 없었어요. 거기서 로그인한 다음 ‘대신 설정해 주기’를 눌러 Genex가 마무리하게 하세요.",
  "Roblox Studio isn't on this computer.": "이 컴퓨터에 Roblox Studio가 없어요.",
  "Roblox Studio isn't on this computer. Open this to get it.":
    "이 컴퓨터에 Roblox Studio가 없어요. 여기를 열어서 받으세요.",
  "Roblox Studio isn't on this computer. Press Get Roblox Studio first.":
    "이 컴퓨터에 Roblox Studio가 없어요. 먼저 ‘Roblox Studio 받기’를 누르세요.",
  "Roblox Studio isn't open.": "Roblox Studio가 열려 있지 않아요.",
  "Roblox Studio runs on a Mac or on Windows only.": "Roblox Studio는 Mac이나 Windows에서만 실행돼요.",
